def solve(g, mark, fill):
    h=len(g); w=len(g[0])
    M={(i,j) for i in range(h) for j in range(w) if g[i][j]==mark}
    out=[row[:] for row in g]
    # try each triple as three corners of a rect: a,b same row; c in col of b. Then 4th corner d=(a.r,c.col). If d has mark or bg -> draw.
    changed=False
    for a in list(M):
        for b in list(M):
            if b<=a: continue
            if a[0]!=b[0]: continue
            for c in list(M):
                if c<=a: continue
                if c[1]!=b[1] or c[0]!=a[0]+1: continue
                d=(b[0],c[1])
                if d in M: continue  # already 4 corners... would skip? demo1 had only 3. allow anyway: still fill border since 3 markers are corners.
                # actually require exactly 3 markers forming L; the 4th missing -> fill
                rs={a[0],d[0]}; cs={a[1],c[1]}
                for rr in [min(rs),max(rs)]:
                    for cc in [min(cs),max(cs)]:
                        out[rr][cc]=fill
                for ii in [min(rs),max(rs)]:
                    for cc in range(min(cs),max(cs)+1):
                        out[ii][cc]=fill
    return out

